import os, socket, threading, time, struct, subprocess, json

fake="/tmp/fakehome2"; cfg="/tmp/test_pueue.yml"; sock_path=f"{fake}/.local/share/pueue/pueue_agent.socket"
env=os.environ.copy(); env["HOME"]=fake

# Minimal CBOR encoder for testing responses
def cbor_encode(obj):
    # support None, bool, int, str, bytes, list, dict
    out=b""
    if obj is None:
        return b'\xf6'
    elif isinstance(obj, bool):
        return b'\xf5' if obj else b'\xf4'
    elif isinstance(obj, int):
        if 0 <= obj <= 23:
            return bytes([obj])
        elif 0 <= obj <= 255:
            return b'\x18'+bytes([obj])
        elif 0 <= obj <= 65535:
            return struct.pack('>BH', 0x19, obj)
        elif 0 <= obj <= 4294967295:
            return struct.pack('>BI', 0x1a, obj)
        elif 0 <= obj <= 18446744073709551615:
            return struct.pack('>BQ', 0x1b, obj)
        elif -24 <= obj <= -1:
            return bytes([0x20 + (obj+32)])  # negative fix? Actually CBOR negative: major 1, value = -1 - n => encode n as uint
            # For -1 => 0x20, -2=>0x21, etc.
        else:
            # generic negative
            n = -1 - obj
            if n <= 23:
                return bytes([0x20 | n])
            elif n <= 255:
                return b'\x38'+bytes([n])
            elif n <= 65535:
                return struct.pack('>BH', 0x39, n)
            elif n <= 4294967295:
                return struct.pack('>BI', 0x3a, n)
            else:
                return struct.pack('>BQ', 0x3b, n)
    elif isinstance(obj, str):
        b=obj.encode()
        l=len(b)
        if l<=23:
            return bytes([0x60|l])+b
        elif l<=255:
            return b'\x78'+bytes([l])+b
        elif l<=65535:
            return struct.pack('>BH', 0x79, l)+b
        else:
            return struct.pack('>BI', 0x7a, l)+b
    elif isinstance(obj, bytes):
        l=len(obj)
        if l<=23:
            return bytes([0x40|l])+obj
        elif l<=255:
            return b'\x58'+bytes([l])+obj
        else:
            return struct.pack('>BH', 0x59, l)+obj
    elif isinstance(obj, list):
        l=len(obj)
        if l<=23:
            hdr=bytes([0x80|l])
        elif l<=255:
            hdr=b'\x98'+bytes([l])
        else:
            hdr=struct.pack('>BH', 0x99, l)
        return hdr+b''.join(cbor_encode(x) for x in obj)
    elif isinstance(obj, dict):
        l=len(obj)
        if l<=23:
            hdr=bytes([0xa0|l])
        elif l<=255:
            hdr=b'\xb8'+bytes([l])
        else:
            hdr=struct.pack('>BH', 0xb9, l)
        body=b""
        for k,v in obj.items():
            body+=cbor_encode(k)+cbor_encode(v)
        return hdr+body
    elif isinstance(obj, float):
        return struct.pack('>Bd', 0xfb, obj)
    else:
        raise Exception(f"unknown {type(obj)}")

# Test encoder matches earlier payloads
print(cbor_encode({"Clean": {"successful_only": False, "group": None}}).hex())
print(cbor_encode("Status").hex(), "expected 66537461747573")

def test_status_response(resp_obj):
    try: os.unlink(sock_path)
    except: pass
    s=socket.socket(socket.AF_UNIX, socket.SOCK_STREAM)
    s.bind(sock_path); s.listen(1); s.settimeout(8)
    def srv():
        try:
            conn,_=s.accept(); conn.settimeout(5)
            hdr=conn.recv(8); n=struct.unpack('>Q',hdr)[0]
            sec=b""
            while len(sec)<n: sec+=conn.recv(n-len(sec))
            v=b"4.0.4"; conn.sendall(struct.pack('>Q',len(v))+v)
            # read Status request
            h=conn.recv(8); nn=struct.unpack('>Q',h)[0]
            pl=b""
            while len(pl)<nn: pl+=conn.recv(nn-len(pl))
            print(f"got req {pl.hex()}")
            # send response
            enc=cbor_encode(resp_obj)
            print(f"sending resp {enc.hex()[:500]} len {len(enc)}")
            conn.sendall(struct.pack('>Q',len(enc))+enc)
            # try to read more? For status, client may just close after response? Let's wait
            conn.settimeout(3)
            try:
                while True:
                    h2=conn.recv(8)
                    if not h2 or len(h2)<8:
                        print("no more hdr", h2)
                        break
                    nn2=struct.unpack('>Q',h2)[0]
                    print(f"second req len {nn2}")
                    pl2=b""
                    while len(pl2)<nn2: pl2+=conn.recv(nn2-len(pl2))
                    print(f"second req {pl2[:500]!r}")
                    break
            except Exception as e:
                print("second read exc", e)
            time.sleep(0.2); conn.close()
        except Exception as e:
            print("srv exc", e)
            import traceback; traceback.print_exc()
        finally: s.close()
    import threading
    t=threading.Thread(target=srv, daemon=True); t.start(); time.sleep(0.3)
    r=subprocess.run(["./executable","-c",cfg,"status"], capture_output=True, text=True, env=env, timeout=10)
    print("STDOUT:", r.stdout[:3000])
    print("STDERR:", r.stderr[:3000])
    print("RC:", r.returncode)
