env=os.environ.copy(); env["HOME"]=fake
def cbor_decode(data):
    import struct as S
    def dec(pos):
        b=data[pos]; pos+=1; major=(b>>5)&0x7; info=b&0x1f
        def ru(info,pos):
            if info<24: return info,pos
            elif info==24: return data[pos],pos+1
            elif info==25: return S.unpack('>H',data[pos:pos+2])[0],pos+2
            elif info==26: return S.unpack('>I',data[pos:pos+4])[0],pos+4
            elif info==27: return S.unpack('>Q',data[pos:pos+8])[0],pos+8
            else: raise Exception(info)
        if major==0:
            v,p=ru(info,pos); return v,p
        elif major==1:
            v,p=ru(info,pos); return -1-v,p
        elif major==2:
            l,p=ru(info,pos); return data[p:p+l],p+l
        elif major==3:
            l,p=ru(info,pos); return data[p:p+l].decode(),p+l
        elif major==4:
            l,p=ru(info,pos); arr=[]
            for _ in range(l):
                v,p=dec(p); arr.append(v)
            return arr,p
        elif major==5:
            l,p=ru(info,pos); m={}
            for _ in range(l):
                k,p=dec(p); v,p=dec(p); m[k]=v
            return m,p
        elif major==7:
            if info==20: return False,p
            if info==21: return True,p
            if info==22 or info==23: return None,p
            if info==26: return S.unpack('>f',data[p:p+4])[0],p+4
            if info==27: return S.unpack('>d',data[p:p+8])[0],p+8
            raise Exception(f"7:{info}")
        else: raise Exception(major)
    v,_=dec(0); return v

