                sys.exit(2)
            opts["failed_in_group"]=a[len("--failed-in-group="):]
            seen_failed_in_group=True
            j+=1
        elif a in ("-k", "--immediate"):
            opts["immediate"]=True
            j+=1
        elif a in ("-s", "--stashed"):
            opts["stashed"]=True
            j+=1
        elif a in ("-i", "--in-place"):
            opts["in_place"]=True
            j+=1
        elif a == "--not-in-place":
            opts["not_in_place"]=True
            j+=1
        elif a in ("-e", "--edit"):
            opts["edit"]=True
            j+=1
        elif a.startswith("-") and a not in ("-", "--"):
            sys.stderr.write("error: unexpected argument '" + a + "' found\n")
            sys.stderr.write("\n  tip: to pass '" + a + "' as a value, use '-- " + a + "'\n")
            sys.stderr.write("\nUsage: " + bn + " restart [OPTIONS] [TASK_IDS]...\n")
            sys.stderr.write("\nFor more information, try '--help'.\n")
            sys.exit(2)
        else:
            pos_before.append(a)
            j+=1
    all_pos = pos_before + after
    ids=[]
    for s in all_pos:
        try:
            if s.startswith("-") and s not in after:
