    return re.sub(r'\d\d:\d\d:\d\d', 'HH:MM:SS', r.stdout), re.sub(r'\d\d:\d\d:\d\d', 'HH:MM:SS', r.stderr), r.returncode
def run_clone(*args, env=None):
    e=os.environ.copy()
    if env: e.update(env)
    r=subprocess.run(["./executable_test"]+list(args), capture_output=True, text=True, env=e)
    o=r.stdout.replace("executable_test","executable")
    e2=r.stderr.replace("executable_test","executable")
    o=re.sub(r'\d\d:\d\d:\d\d', 'HH:MM:SS', o)
    e2=re.sub(r'\d\d:\d\d:\d\d', 'HH:MM:SS', e2)
